import{_ as e,c as t,o,a4 as r}from"./chunks/framework.BYxathSa.js";const h=JSON.parse('{"title":"Q10：useRef 的作用与用法","description":"","frontmatter":{},"headers":[],"relativePath":"react/q10.md","filePath":"react/q10.md","lastUpdated":null}'),a={name:"react/q10.md"},s=r('<h1 id="q10-useref-的作用与用法" tabindex="-1">Q10：<code>useRef</code> 的作用与用法 <a class="header-anchor" href="#q10-useref-的作用与用法" aria-label="Permalink to &quot;Q10：`useRef` 的作用与用法&quot;">​</a></h1><p><code>const ref = useRef(initialValue)</code> 返回一个可变对象，其 <code>.current</code> 属性在整个生命周期中保持不变，修改它不会触发重新渲染。</p><p><strong>主要用途</strong>：</p><ol><li><strong>访问 DOM 元素</strong>：绑定到 JSX 的 <code>ref</code> 属性上，获取真实 DOM 节点进行操作（focus、测量等）。</li><li><strong>保存可变值</strong>：存放与视图无关但需要跨渲染保持不变的数据（如定时器 ID、上一次的状态）。</li><li><strong>解决闭包陷阱</strong>：将最新 state/props 同步到 ref，在异步回调中通过 <code>ref.current</code> 获取最新值。</li></ol>',4),c=[s];function n(d,_,i,l,f,p){return o(),t("div",null,c)}const m=e(a,[["render",n]]);export{h as __pageData,m as default};
